// Consistency of the Learn page with the Solver's method catalogue (docs/assets/methods.js):
//  - learn.html loads vrp.js, methods.js and catalogue.js (in that order) and has the catalogue container;
//  - every reference key used by a method, and every key of VRP.REF_SHORT, has an element id="ref-<key>" whose entry
//    names the first author and the year of the short label;
//  - the catalogue generated by catalogue.js lists all 20 methods and every internal link resolves;
//  - ids are unique and every in-page link (#...) has a target.
const fs = require('fs'), path = require('path'), vm = require('vm'), assert = require('assert');
const root = [path.join(__dirname, '..'), path.join(__dirname, '..', '..')].find(r => fs.existsSync(path.join(r, 'docs', 'assets', 'vrp.js')));
const V = require(path.join(root, 'docs', 'assets', 'vrp.js'));
require(path.join(root, 'docs', 'assets', 'methods.js'));
const html = fs.readFileSync(path.join(root, 'docs', 'learn.html'), 'utf8');
let passed = 0;
const test = (name, fn) => { fn(); passed++; console.log('[ ok ] ' + name); };

const ids = [...html.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]);

test('scripts are loaded in dependency order', () => {
  const pos = f => html.indexOf('src="assets/' + f + '"');
  for (const f of ['vrp.js', 'methods.js', 'catalogue.js']) assert.ok(pos(f) > 0, f + ' not loaded');
  assert.ok(pos('vrp.js') < pos('methods.js') && pos('methods.js') < pos('catalogue.js'));
  assert.ok(ids.includes('method-catalogue'));
});

test('ids are unique', () => {
  const seen = new Set(), dup = [];
  ids.forEach(i => { if (seen.has(i)) dup.push(i); seen.add(i); });
  assert.deepStrictEqual(dup, []);
});

test('every in-page link has a target', () => {
  const missing = [...html.matchAll(/href="#([^"]+)"/g)].map(m => m[1]).filter(t => !ids.includes(t));
  assert.deepStrictEqual([...new Set(missing)], []);
});

const keys = new Set(Object.keys(V.REF_SHORT));
Object.values(V.METHODS).forEach(m => m.refs.forEach(k => keys.add(k)));

test('every reference key has an entry that matches its short label', () => {
  assert.ok(keys.size >= 29);
  for (const k of keys) {
    assert.ok(ids.includes('ref-' + k), 'no element id="ref-' + k + '" in learn.html');
    assert.ok(V.REF_SHORT[k], 'no short label for ' + k);
    const at = html.indexOf('id="ref-' + k + '"');
    const li = html.slice(html.lastIndexOf('<li', at), html.indexOf('</li>', at));
    const label = V.REF_SHORT[k], year = (label.match(/\((\d{4})\)/) || [])[1];
    const surname = label.replace(/\s*\(\d{4}\)/, '').split(/ &|,| et al/)[0].trim();
    assert.ok(li.includes(year), k + ': year ' + year + ' missing in its entry');
    assert.ok(li.includes(surname), k + ': surname ' + surname + ' missing in its entry');
  }
});

test('catalogue.js renders all methods with resolvable links', () => {
  const host = { innerHTML: '' };
  const sandbox = { window: { VRP: V }, document: { getElementById: id => (id === 'method-catalogue' ? host : null) } };
  vm.runInNewContext(fs.readFileSync(path.join(root, 'docs', 'assets', 'catalogue.js'), 'utf8'), sandbox);
  const rows = [...host.innerHTML.matchAll(/<tr id="m-([a-z]+)">/g)].map(m => m[1]);
  assert.deepStrictEqual(rows.slice().sort(), Object.keys(V.METHODS).sort());
  assert.strictEqual(rows.length, 20);
  const links = [...host.innerHTML.matchAll(/href="#([^"]+)"/g)].map(m => m[1]);
  assert.ok(links.length >= 25);
  assert.deepStrictEqual(links.filter(t => !ids.includes(t)), []);
  for (const g of Object.values(V.METHOD_GROUPS)) assert.ok(host.innerHTML.includes(g.replace(/&/g, '&amp;')), g);
});

console.log(passed + ' passed');
